<script>
import mpx, { createPage } from '@mpxjs/core'
import { fetchTrendingKeywords, requestSuggestions } from '../../services/search'

createPage({
  data: {
    keyword: '',
    trendingKeywords: [],
    suggestions: [],
    suggestionRequest: null,
    searchVersion: 0,
    isUnloaded: false
  },
  onLoad () {
    fetchTrendingKeywords()
      .then((keywords) => {
        if (!this.isUnloaded) this.trendingKeywords = keywords
      })
      .catch(() => {
        if (!this.isUnloaded) this.showSearchError()
      })
  },
  onUnload () {
    this.isUnloaded = true
    this.searchVersion++
    this.cancelSuggestionRequest()
  },
  methods: {
    onKeywordInput (event) {
      this.search(event.detail.value.trim())
    },
    chooseKeyword (keyword) {
      this.search(keyword)
    },
    search (keyword) {
      const version = ++this.searchVersion
      this.keyword = keyword
      this.cancelSuggestionRequest()

      if (!keyword) {
        this.suggestions = []
        return
      }

      const request = requestSuggestions(keyword)
      this.suggestionRequest = request
      request
        .then(({ data }) => {
          if (!this.isUnloaded && version === this.searchVersion) {
            this.suggestions = data.list
          }
        })
        .catch(() => {
          if (!this.isUnloaded && version === this.searchVersion) {
            this.showSearchError()
          }
        })
        .then(() => {
          if (this.suggestionRequest === request) this.suggestionRequest = null
        })
    },
    cancelSuggestionRequest () {
      const request = this.suggestionRequest
      if (request && request.__returned) request.__returned.abort()
      this.suggestionRequest = null
    },
    showSearchError () {
      mpx.showToast({
        title: '搜索失败',
        icon: 'none'
      })
    },
    openProduct (productId) {
      mpx.navigateTo({
        url: `/pages/product/detail?id=${productId}`
      })
    }
  }
})
</script>

<style scoped>
.search-page { padding: 24rpx; }
.trending, .suggestions { margin-top: 24rpx; }
</style>
